 "content": "def transform(grid):
    """Rotate the 3x3 tile 180 degrees, then mirror-tile it in both axes."""
    h, w = len(grid), len(grid[0])
    def mirrored_index(i, size):
        tile, inner = divmod(i, size)
        return inner if tile in (0, 2) else size - 1 - inner
    return [
        [grid[h - 1 - mirrored_index(r, h)][w - 1 - mirrored_index(c, w)]
         for c in range(3 * w)]
        for r in range(3 * h)
    ]
